CREATE TABLE "signature_versions" (
    "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "signature_id" INTEGER NOT NULL,
    "version_number" INTEGER NOT NULL,
    "signature_image_path" TEXT NOT NULL,
    "change_description" TEXT,
    "is_active" INTEGER DEFAULT 1,
    "created_by" INTEGER,
    "created_at" TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP
);

-- Table: "signatures"
CREATE TABLE "signatures" (
    "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "document_id" INTEGER NOT NULL,
    "user_id" INTEGER NOT NULL,
    "signature_hash" TEXT NOT NULL,
    "certificate_info" TEXT,
    "signed_at" TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP,
    "pdf_path" TEXT
);

-- Table: "staff"
CREATE TABLE "staff" (
    "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "matricule" TEXT UNIQUE,
    "nom" TEXT NOT NULL,
    "prenoms" TEXT NOT NULL,
    "nationality" TEXT DEFAULT 'Guinéenne',
    "fonction" TEXT NOT NULL,
    "service_id" INTEGER,
    "telephone" TEXT,
    "email" TEXT,
    "status" TEXT DEFAULT 'ACTIF',
    "is_driver" INTEGER DEFAULT 0,
    "created_at" TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP,
    "updated_at" TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP
);

-- Table: "template_fields"
CREATE TABLE "template_fields" (
    "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "template_id" INTEGER NOT NULL,
    "field_name" TEXT NOT NULL,
    "label" TEXT NOT NULL,
    "field_type" TEXT NOT NULL,
    "required" INTEGER DEFAULT 0,
    "data_source" TEXT,
    "default_value" TEXT,
    "position" INTEGER DEFAULT 0,
    "created_at" TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP
);

-- Table: "template_versions"
CREATE TABLE "template_versions" (
    "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "template_id" INTEGER NOT NULL,
    "version" INTEGER NOT NULL,
    "file_path" TEXT,
    "header_text" TEXT,
    "footer_text" TEXT,
    "status" TEXT DEFAULT 'ACTIVE',
    "created_by" INTEGER,
    "created_at" TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP,
    "version_number" INTEGER DEFAULT 1,
    "file_type" TEXT,
    "change_description" TEXT,
    "uploaded_by" INTEGER,
    "content_body_html" TEXT,
    "editor_type" TEXT DEFAULT 'UK_GED_EDITOR'
);

-- Table: "user_signatures"
CREATE TABLE "user_signatures" (
    "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "user_id" INTEGER NOT NULL,
    "function_title" TEXT,
    "service_id" INTEGER,
    "signature_image_path" TEXT NOT NULL,
    "activation_date" DATE,
    "expiration_date" DATE,
    "status" TEXT DEFAULT 'ACTIVE',
    "width" INTEGER DEFAULT 150,
    "height" INTEGER DEFAULT 60,
    "alignment" TEXT DEFAULT 'RIGHT',
    "created_at" TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP,
    "updated_at" TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP,
    "version_number" INTEGER DEFAULT 1,
    "is_active" INTEGER DEFAULT 1,
    "created_by" INTEGER
);

-- Table: "users"
CREATE TABLE "users" (
    "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "matricule" TEXT NOT NULL UNIQUE,
    "first_name" TEXT NOT NULL,
    "last_name" TEXT NOT NULL,
    "email" TEXT NOT NULL UNIQUE,
    "phone" TEXT,
    "function_title" TEXT NOT NULL,
    "personnel_category" TEXT DEFAULT 'PERSONNEL_ADMINISTRATIF',
    "academic_structure" TEXT,
    "service_id" INTEGER,
    "role_id" INTEGER NOT NULL,
    "password_hash" TEXT NOT NULL,
    "can_receive_appointments" INTEGER DEFAULT 1,
    "status" TEXT NOT NULL DEFAULT 'ACTIVE',
    "last_login" TIMESTAMPTZ,
    "created_at" TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP,
    "updated_at" TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP
);

-- Table: "users_temp"
CREATE TABLE "users_temp" (
    "id" INTEGER,
    "matricule" TEXT,
    "first_name" TEXT,
    "last_name" TEXT,
    "email" TEXT,
    "phone" TEXT,
    "function_title" TEXT,
    "service_id" INTEGER,
    "role_id" INTEGER,
    "password_hash" TEXT,
    "status" TEXT,
    "last_login" TIMESTAMPTZ,
    "created_at" TIMESTAMPTZ,
    "updated_at" TIMESTAMPTZ,
    "can_receive_appointments" INTEGER,
    "personnel_category" TEXT,
    "academic_structure" TEXT
);

-- Table: "vehicles"
CREATE TABLE "vehicles" (
    "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "registration_number" TEXT NOT NULL,
    "brand" TEXT,
    "model" TEXT,
    "assigned_staff_id" INTEGER,
    "status" TEXT DEFAULT 'ACTIF',
    "created_at" TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP,
    "updated_at" TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP
);

