UNIVERSITÉ DE KINDIA', 'UNIVERSITÉ DE KINDIA • Cabinet du Recteur', 'CENTER', 12, 10, 1, 1, NULL, '2026-08-17 20:51:33', '2026-08-18 01:58:16', 'Actes Officiels', 1, 1, 'template_1787018257561_modele_arrete.docx', NULL, NULL, NULL, 'DOCX', 0, NULL, 'Helvetica', 12, '#0B2545', '#D4AF37', '<p style="text-align:center; margin-bottom:8px; line-height:1.6; color:#1E293B;"><span style="color:#0B2545; font-size:12px"><strong>RÉPUBLIQUE DE GUINÉE</strong></span></p>
<p style="text-align:center; margin-bottom:8px; line-height:1.6; color:#1E293B;"><span style="color:#D4AF37; font-size:10px"><em>Travail – Justice – Solidarité</em></span></p>
<p style="text-align:center; margin-bottom:8px; line-height:1.6; color:#1E293B;"><span style="color:#0B2545; font-size:11px"><strong>MINISTÈRE DE L''ENSEIGNEMENT SUPÉRIEUR, DE LA RECHERCHE SCIENTIFIQUE ET DE L''INNOVATION</strong></span></p>
<p style="text-align:center; margin-bottom:8px; line-height:1.6; color:#1E293B;"><span style="color:#0B2545; font-size:13px"><strong>UNIVERSITÉ DE KINDIA</strong></span></p>
<p style="text-align:center; margin-bottom:8px; line-height:1.6; color:#1E293B;"><span style="color:#475569; font-size:11px"><strong>SECRÉTARIAT GÉNÉRAL</strong></span></p>
<p style="text-align: center; margin-bottom: 8px; min-height: 1em;">&nbsp;<u style="color: rgb(11, 37, 69); font-size: 16px; text-align: center;"><strong>ORDRE DE MISSION</strong></u></p>
<p style="text-align:center; margin-bottom:8px; line-height:1.6; color:#1E293B;"><span style="color:#D4AF37; font-size:11px"><strong>N° <span data-field-key="&lt;span data-field-key=" {{reference}}"="" class="dynamic-tag" contenteditable="false" style="background-color:#EFF6FF; color:#1E40AF; padding:2px 8px; border-radius:6px; font-family:monospace; font-weight:bold; border:1px solid #BFDBFE; display:inline-block; margin:0 2px;">🏷️ {{reference}}</span>" class="dynamic-tag" contenteditable="false" style="background-color:#EFF6FF; color:#1E40AF; padding:2px 8px; border-radius:6px; font-family:monospace; font-weight:bold; border:1px solid #BFDBFE; display:inline-block; margin:0 2px;"&gt;🏷️ <span data-field-key="{{reference}}" class="dynamic-tag" contenteditable="false" style="background-color:#EFF6FF; color:#1E40AF; padding:2px 8px; border-radius:6px; font-family:monospace; font-weight:bold; border:1px solid #BFDBFE; display:inline-block; margin:0 2px;">🏷️ {{reference}}</span></strong></span></p>
<p style="text-align:left; margin-bottom:8px; min-height:1em;">&nbsp;</p>
<p style="text-align:left; margin-bottom:8px; line-height:1.6; color:#1E293B;"><span style="font-size:12px"><strong>Il est ordonné à : </strong></span><span style="color:#0B2545; font-size:12px"><strong><span data-field-key="&lt;span data-field-key=" {{missionnaire_prenoms}}"="" class="dynamic-tag" contenteditable="false" style="background-color:#EFF6FF; color:#1E40AF; padding:2px 8px; border-radius:6px; font-family:monospace; font-weight:bold; border:1px solid #BFDBFE; display:inline-block; margin:0 2px;">🏷️ {{missionnaire_prenoms}}</span>" class="dynamic-tag" contenteditable="false" style="background-color:#EFF6FF; color:#1E40AF; padding:2px 8px; border-radius:6px; font-family:monospace; font-weight:bold; border:1px solid #BFDBFE; display:inline-block; margin:0 2px;"&gt;🏷️ <span data-field-key="{{missionnaire_prenoms}}" class="dynamic-tag" contenteditable="false" style="background-color:#EFF6FF; color:#1E40AF; padding:2px 8px; border-radius:6px; font-family:monospace; font-weight:bold; border:1px solid #BFDBFE; display:inline-block; margin:0 2px;">🏷️ {{missionnaire_prenoms}}</span></strong></span><strong> <span data-field-key="&lt;span data-field-key=" {{missionnaire_nom}}"="" class="dynamic-tag" contenteditable="false" style="background-color:#EFF6FF; color:#1E40AF; padding:2px 8px; border-radius:6px; font-family:monospace; font-weight:bold; border:1px solid #BFDBFE; display:inline-block; margin:0 2px;">🏷️ {{missionnaire_nom}}</span>" class="dynamic-tag" contenteditable="false" style="background-color:#EFF6FF; color:#1E40AF; padding:2px 8px; border-radius:6px; font-family:monospace; font-weight:bold; border:1px solid #BFDBFE; display:inline-block; margin:0 2px;"&gt;🏷️ <span data-field-key="{{missionnaire_nom}}" class="dynamic-tag" contenteditable="false" style="background-color:#EFF6FF; color:#1E40AF; padding:2px 8px; border-radius:6px; font-family:monospace; font-weight:bold; border:1px solid #BFDBFE; display:inline-block; margin:0 2px;">🏷️ {{missionnaire_nom}}</span></strong></p>
<p style="text-align:left; margin-bottom:8px; line-height:1.6; color:#1E293B;"><span style="font-size:12px"><strong>Fonction : </strong></span><span style="font-size:12px"><span data-field-key="&lt;span data-field-key=" {{missionnaire_fonction}}"="" class="dynamic-tag" contenteditable="false" style="background-color:#EFF6FF; color:#1E40AF; padding:2px 8px; border-radius:6px; font-family:monospace; font-weight:bold; border:1px solid #BFDBFE; display:inline-block; margin:0 2px;">🏷️ {{missionnaire_fonction}}</span>" class="dynamic-tag" contenteditable="false" style="background-color:#EFF6FF; color:#1E40AF; padding:2px 8px; border-radius:6px; font-family:monospace; font-weight:bold; border:1px solid #BFDBFE; display:inline-block; margin:0 2px;"&gt;🏷️ <span data-field-key="{{missionnaire_fonction}}" class="dynamic-tag" contenteditable="false" style="background-color:#EFF6FF; color:#1E40AF; padding:2px 8px; border-radius:6px; font-family:monospace; font-weight:bold; border:1px solid #BFDBFE; display:inline-block; margin:0 2px;">🏷️ {{missionnaire_fonction}}</span></span></p>
<p style="text-align:left; margin-bottom:8px; line-height:1.6; color:#1E293B;"><span style="font-size:12px"><strong>Service / Faculté : </strong></span><span style="font-size:12px"><span data-field-key="&lt;span data-field-key=" {{missionnaire_service}}"="" class="dynamic-tag" contenteditable="false" style="background-color:#EFF6FF; color:#1E40AF; padding:2px 8px; border-radius:6px; font-family:monospace; font-weight:bold; border:1px solid #BFDBFE; display:inline-block; margin:0 2px;">🏷️ {{missionnaire_service}}</span>" class="dynamic-tag" contenteditable="false" style="background-color:#EFF6FF; color:#1E40AF; padding:2px 8px; border-radius:6px; font-family:monospace; font-weight:bold; border:1px solid #BFDBFE; display:inline-block; margin:0 2px;"&gt;🏷️ <span data-field-key="{{missionnaire_service}}" class="dynamic-tag" contenteditable="false" style="background-color:#EFF6FF; color:#1E40AF; padding:2px 8px; border-radius:6px; font-family:monospace; font-weight:bold; border:1px solid #BFDBFE; display:inline-block; margin:0 2px;">🏷️ {{missionnaire_service}}</span></span></p>
<p style="text-align:left; margin-bottom:8px; line-height:1.6; color:#1E293B;"><span style="font-size:12px"><strong>Matricule : </strong></span><span style="font-size:12px"><span data-field-key="&lt;span data-field-key=" {{matricule}}"="" class="dynamic-tag" contenteditable="false" style="background-color:#EFF6FF; color:#1E40AF; padding:2px 8px; border-radius:6px; font-family:monospace; font-weight:bold; border:1px solid #BFDBFE; display:inline-block; margin:0 2px;">🏷️ {{matricule}}</span>" class="dynamic-tag" contenteditable="false" style="background-color:#EFF6FF; color:#1E40AF; padding:2px 8px; border-radius:6px; font-family:monospace; font-weight:bold; border:1px solid #BFDBFE; display:inline-block; margin:0 2px;"&gt;🏷️ <span data-field-key="{{matricule}}" class="dynamic-tag" contenteditable="false" style="background-color:#EFF6FF; color:#1E40AF; padding:2px 8px; border-radius:6px; font-family:monospace; font-weight:bold; border:1px solid #BFDBFE; display:inline-block; margin:0 2px;">🏷️ {{matricule}}</span></span></p>
<p style="text-align:left; margin-bottom:8px; line-height:1.6; color:#1E293B;"><span style="font-size:12px"><strong>De se rendre à : </strong></span><span style="font-size:12px"><strong><span data-field-key="&lt;span data-field-key=" {{destination}}"="" class="dynamic-tag" contenteditable="false" style="background-color:#EFF6FF; color:#1E40AF; padding:2px 8px; border-radius:6px; font-family:monospace; font-weight:bold; border:1px solid #BFDBFE; display:inline-block; margin:0 2px;">🏷️ {{destination}}</span>" class="dynamic-tag" contenteditable="false" style="background-color:#EFF6FF; color:#1E40AF; padding:2px 8px; border-radius:6px; font-family:monospace; font-weight:bold; border:1px solid #BFDBFE; display:inline-block; margin:0 2px;"&gt;🏷️ <span data-field-key="{{destination}}" class="dynamic-tag" contenteditable="false" style="background-color:#EFF6FF; color:#1E40AF; padding:2px 8px; border-radius:6px; font-family:monospace; font-weight:bold; border:1px solid #BFDBFE; display:inline-block; margin:0 2px;">🏷️ {{destination}}</span></strong></span></p>
<p style="text-align:left; margin-bottom:8px; line-height:1.6; color:#1E293B;"><span style="font-size:12px"><strong>Objet de la Mission : </strong></span><span style="font-size:12px"><span data-field-key="&lt;span data-field-key=" {{objet_mission}}"="" class="dynamic-tag" contenteditable="false" style="background-color:#EFF6FF; color:#1E40AF; padding:2px 8px; border-radius:6px; font-family:monospace; font-weight:bold; border:1px solid #BFDBFE; display:inline-block; margin:0 2px;">🏷️ {{objet_mission}}</span>" class="dynamic-tag" contenteditable="false" style="background-color:#EFF6FF; color:#1E40AF; padding:2px 8px; border-radius:6px; font-family:monospace; font-weight:bold; border:1px solid #BFDBFE; display:inline-block; margin:0 2px;"&gt;🏷️ <span data-field-key="{{objet_mission}}" class="dynamic-tag" contenteditable="false" style="background-color:#EFF6FF; color:#1E40AF; padding:2px 8px; border-radius:6px; font-family:monospace; font-weight:bold; border:1px solid #BFDBFE; display:inline-block; margin:0 2px;">🏷️ {{objet_mission}}</span></span></p>
<p style="text-align:left; margin-bottom:8px; line-height:1.6; color:#1E293B;"><span style="font-size:12px"><strong>Moyen de Transport : </strong></span><span style="font-size:12px"><span data-field-key="&lt;span data-field-key=" {{moyen_transport}}"="" class="dynamic-tag" contenteditable="false" style="background-color:#EFF6FF; color:#1E40AF; padding:2px 8px; border-radius:6px; font-family:monospace; font-weight:bold; border:1px solid #BFDBFE; display:inline-block; margin:0 2px;">🏷️ {{moyen_transport}}</span>" class="dynamic-tag" contenteditable="false" style="background-color:#EFF6FF; color:#1E40AF; padding:2px 8px; border-radius:6px; font-family:monospace; font-weight:bold; border:1px solid #BFDBFE; display:inline-block; margin:0 2px;"&gt;🏷️ <span data-field-key="{{moyen_transport}}" class="dynamic-tag" contenteditable="false" style="background-color:#EFF6FF; color:#1E40AF; padding:2px 8px; border-radius:6px; font-family:monospace; font-weight:bold; border:1px solid #BFDBFE; display:inline-block; margin:0 2px;">🏷️ {{moyen_transport}}</span></span></p>
<p style="text-align:left; margin-bottom:8px; line-height:1.6; color:#1E293B;"><span style="font-size:12px"><strong>Date de Départ : </strong></span><span style="font-size:12px"><span data-field-key="&lt;span data-field-key=" {{date_depart}}"="" class="dynamic-tag" contenteditable="false" style="background-color:#EFF6FF; color:#1E40AF; padding:2px 8px; border-radius:6px; font-family:monospace; font-weight:bold; border:1px solid #BFDBFE; display:inline-block; margin:0 2px;">🏷️ {{date_depart}}</span>" class="dynamic-tag" contenteditable="false" style="background-color:#EFF6FF; color:#1E40AF; padding:2px 8px; border-radius:6px; font-family:monospace; font-weight:bold; border:1px solid #BFDBFE; display:inline-block; margin:0 2px;"&gt;🏷️ <span data-field-key="{{date_depart}}" class="dynamic-tag" contenteditable="false" style="background-color:#EFF6FF; color:#1E40AF; padding:2px 8px; border-radius:6px; font-family:monospace; font-weight:bold; border:1px solid #BFDBFE; display:inline-block; margin:0 2px;">🏷️ {{date_depart}}</span></span></p>
<p style="text-align:left; margin-bottom:8px; line-height:1.6; color:#1E293B;"><span style="font-size:12px"><strong>Date de retour : </strong></span><span style="font-size:12px"><span data-field-key="&lt;span data-field-key=" {{date_retour}}"="" class="dynamic-tag" contenteditable="false" style="background-color:#EFF6FF; color:#1E40AF; padding:2px 8px; border-radius:6px; font-family:monospace; font-weight:bold; border:1px solid #BFDBFE; display:inline-block; margin:0 2px;">🏷️ {{date_retour}}</span>" class="dynamic-tag" contenteditable="false" style="background-color:#EFF6FF; color:#1E40AF; padding:2px 8px; border-radius:6px; font-family:monospace; font-weight:bold; border:1px solid #BFDBFE; display:inline-block; margin:0 2px;"&gt;🏷️ <span data-field-key="{{date_retour}}" class="dynamic-tag" contenteditable="false" style="background-color:#EFF6FF; color:#1E40AF; padding:2px 8px; border-radius:6px; font-family:monospace; font-weight:bold; border:1px solid #BFDBFE; display:inline-block; margin:0 2px;">🏷️ {{date_retour}}</span></span></p>
<p style="text-align:left; margin-bottom:8px; min-height:1em;">&nbsp;</p>
<p style="text-align:justify; margin-bottom:8px; line-height:1.6; color:#1E293B;"><span style="color:#334155; font-size:11px"><em>Les autorités civiles et militaires des localités traversées sont priées de bien vouloir faciliter l''accomplissement de la présente mission.</em></span></p>
<p style="text-align:left; margin-bottom:8px; min-height:1em;">&nbsp;</p>
<p style="text-align:right; margin-bottom:8px; line-height:1.6; color:#1E293B;"><span style="font-size:11px">Kindia, le <span data-field-key="&lt;span data-field-key=" {{date_document}}"="" class="dynamic-tag" contenteditable="false" style="background-color:#EFF6FF; color:#1E40AF; padding:2px 8px; border-radius:6px; font-family:monospace; font-weight:bold; border:1px solid #BFDBFE; display:inline-block; margin:0 2px;">🏷️ {{date_document}}</span>" class="dynamic-tag" contenteditable="false" style="background-color:#EFF6FF; color:#1E40AF; padding:2px 8px; border-radius:6px; font-family:monospace; font-weight:bold; border:1px solid #BFDBFE; display:inline-block; margin:0 2px;"&gt;🏷️ <span data-field-key="{{date_document}}" class="dynamic-tag" contenteditable="false" style="background-color:#EFF6FF; color:#1E40AF; padding:2px 8px; border-radius:6px; font-family:monospace; font-weight:bold; border:1px solid #BFDBFE; display:inline-block; margin:0 2px;">🏷️ {{date_document}}</span></span></p>
<p style="text-align:right; margin-bottom:8px; line-height:1.6; color:#1E293B;"><span style="color:#0B2545; font-size:12px"><strong>LE SECRÉTAIRE GÉNÉRAL</strong></span></p>
<p style="text-align:right; margin-bottom:8px; line-height:1.6; color:#1E293B;"><span style="color:#94A3B8; font-size:10px">[Signature Électronique &amp; Sceau QR]</span></p>
<p style="text-align:right; margin-bottom:8px; line-height:1.6; color:#1E293B;"><span style="color:#0B2545; font-size:12px"><u><strong><span data-field-key="&lt;span data-field-key=" {{signature_secretaire_general}}"="" class="dynamic-tag" contenteditable="false" style="background-color:#EFF6FF; color:#1E40AF; padding:2px 8px; border-radius:6px; font-family:monospace; font-weight:bold; border:1px solid #BFDBFE; display:inline-block; margin:0 2px;">🏷️ {{signature_secretaire_general}}</span>" class="dynamic-tag" contenteditable="false" style="background-color:#EFF6FF; color:#1E40AF; padding:2px 8px; border-radius:6px; font-family:monospace; font-weight:bold; border:1px solid #BFDBFE; display:inline-block; margin:0 2px;"&gt;🏷️ <span data-field-key="{{signature_secretaire_general}}" class="dynamic-tag" contenteditable="false" style="background-color:#EFF6FF; color:#1E40AF; padding:2px 8px; border-radius:6px; font-family:monospace; font-weight:bold; border:1px solid #BFDBFE; display:inline-block; margin:0 2px;">🏷️ {{signature_secretaire_general}}</span></strong></u></span></p>', NULL, NULL, 'MS_WORD'),
